def maxProductPair(nums, target):
    n = len(nums)
    best = None          # best product found so far (None means no valid pair yet)
    answer = [-1, -1]    # default when no valid pair exists

    for i in range(n):
        for j in range(n):
            # indices must differ, the first value must be strictly larger, and the sum must match
            if i != j and nums[i] > nums[j] and nums[i] + nums[j] == target:
                product = nums[i] * nums[j]
                # keep the pair with the largest product
                if best is None or product > best:
                    best = product
                    answer = [i, j]

    return answer
